// EmployeeDashboard.jsx
import React, { useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import { Link } from 'react-router-dom';
import api from "../api/axios";   // your custom axios instance

const EmployeeDashboard = () => {
  const token = useSelector((state) => state.auth.token);
  const user = useSelector((state) => state.auth.user);

  const [tickets, setTickets] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchTickets = async () => {
      setLoading(true);
      setError(null);
      try {
        const response = await api.get('tickets/');
        // Log the full response to debug if needed
        console.log('Full API response:', response.data);
        console.log('Current user ID:', user?.id);

        // Filter tickets created by the logged-in user
        const myTickets = response.data.filter(
          ticket => ticket.creator?.id === user?.id
        );

        setTickets(myTickets);
      } catch (err) {
        setError('Failed to load tickets. Check console for details.');
        console.error("Could not load your tickets:", err?.response?.data || err.message);
      } finally {
        setLoading(false);
      }
    };

    if (user && token) fetchTickets();
  }, [token, user]);

  // Calculate counts based on statuses (aligned with requirements)
  const countOpen = tickets.filter(t => t.status === 'Open').length;
  const countInProgress = tickets.filter(t => t.status === 'In Progress').length;
  const countResolved = tickets.filter(t => t.status === 'Resolved').length;

  // Helper to get priority color
  const getPriorityColor = (priority) => {
    switch (priority) {
      case 'High': return '#ff4d4f';  // Red
      case 'Medium': return '#faad14';   // Orange
      case 'Low': return '#52c41a';                     // Green
      default: return '#d9d9d9';                        // Gray
    }
  };

  // Helper to get status color
  const getStatusColor = (status) => {
    switch (status) {
      case 'Open': return '#1890ff';       // Blue
      case 'In Progress': return '#faad14';            // Orange
      case 'Resolved': return '#52c41a';                 // Green
      default: return '#d9d9d9';
    }
  };

  if (loading) return <div style={styles.loading}>Loading your tickets...</div>;
  if (error) return <div style={styles.error}>{error}</div>;

  return (
    <div style={styles.container}>
      <h2 style={styles.title}>My Tickets Dashboard</h2>

      {/* Dashboard Counts - Aligned with requirements */}
      <div style={styles.countsGrid}>
        <div style={{ ...styles.countCard, background: '#e6f7ff', borderColor: '#1890ff' }}>
          <h3 style={styles.countNumber}>{countOpen}</h3>
          <p style={styles.countLabel}>Open Tickets</p>
        </div>
        <div style={{ ...styles.countCard, background: '#fffbe6', borderColor: '#faad14' }}>
          <h3 style={styles.countNumber}>{countInProgress}</h3>
          <p style={styles.countLabel}>In Progress</p>
        </div>
        <div style={{ ...styles.countCard, background: '#f6ffed', borderColor: '#52c41a' }}>
          <h3 style={styles.countNumber}>{countResolved}</h3>
          <p style={styles.countLabel}>Resolved</p>
        </div>
      </div>

      {/* Tickets List - Card Layout for Active Tickets (filter out Resolved if desired, but showing all per common practice) */}
      {tickets.length === 0 ? (
        <p style={styles.noTickets}>You haven't created any tickets yet.</p>
      ) : (
        <div style={styles.ticketsContainer}>
          {tickets.map(ticket => (
            <div key={ticket.id} style={styles.ticketCard}>
              <div style={styles.ticketHeader}>
                <h4 style={styles.ticketTitle}>
                  <Link to={`/tickets/${ticket.id}`} style={{ color: 'inherit', textDecoration: 'none' }}>
                    #{ticket.id} - {ticket.title}
                  </Link>
                </h4>
                <span 
                  style={{ 
                    ...styles.badge, 
                    background: getPriorityColor(ticket.priority),
                    color: '#fff'
                  }}
                >
                  Priority: {ticket.priority}
                </span>
                <span 
                  style={{ 
                    ...styles.badge, 
                    background: getStatusColor(ticket.status),
                    color: '#fff'
                  }}
                >
                  Status: {ticket.status}
                </span>
              </div>
              <p style={styles.ticketDescription}>{ticket.description}</p>
              {ticket.created_at && (
                <p style={styles.ticketMeta}>Created: {new Date(ticket.created_at).toLocaleString()}</p>
              )}
              {/* Attachments and confidential_notes handled in detail view */}
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

// Inline styles for clean, attractive UI (no external libs needed)
const styles = {
  container: {
    padding: '24px',
    maxWidth: '1200px',
    margin: '0 auto',
    fontFamily: 'Arial, sans-serif',
    background: '#f0f2f5',
    borderRadius: '8px',
  },
  title: {
    fontSize: '24px',
    marginBottom: '24px',
    color: '#333',
  },
  countsGrid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
    gap: '16px',
    marginBottom: '32px',
  },
  countCard: {
    padding: '16px',
    border: '1px solid',
    borderRadius: '8px',
    textAlign: 'center',
    boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
  },
  countNumber: {
    fontSize: '32px',
    margin: '0',
    color: '#333',
  },
  countLabel: {
    fontSize: '16px',
    color: '#666',
    margin: '8px 0 0',
  },
  ticketsContainer: {
    display: 'flex',
    flexDirection: 'column',
    gap: '16px',
  },
  ticketCard: {
    padding: '16px',
    border: '1px solid #d9d9d9',
    borderRadius: '8px',
    background: '#fff',
    boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
  },
  ticketHeader: {
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
    marginBottom: '8px',
  },
  ticketTitle: {
    margin: '0',
    fontSize: '18px',
    flex: 1,
  },
  badge: {
    padding: '4px 12px',
    borderRadius: '16px',
    fontSize: '12px',
    fontWeight: 'bold',
  },
  ticketDescription: {
    fontSize: '14px',
    color: '#666',
    margin: '0 0 8px',
  },
  ticketMeta: {
    fontSize: '12px',
    color: '#999',
    margin: '0',
  },
  loading: {
    textAlign: 'center',
    fontSize: '18px',
    color: '#1890ff',
  },
  error: {
    textAlign: 'center',
    fontSize: '18px',
    color: '#ff4d4f',
  },
  noTickets: {
    textAlign: 'center',
    fontSize: '16px',
    color: '#666',
  },
};

export default EmployeeDashboard;
